// Phiếu mua hàng đã lập quá 14 ngày mà chưa nhận hoá đơn đỏ — thiếu hoá đơn thì không
// khấu trừ được thuế GTGT đầu vào cho lô đó. Báo NỘI BỘ cho kế toán để gọi lại NCC.
const d = $json;
const items = d.items || [];
const vnd = n => new Intl.NumberFormat('vi-VN').format(n || 0) + '₫';
const STATUS_LABEL = { not_received: 'Chưa nhận HĐ', none: 'Không có HĐ', received: 'Đã nhận HĐ' };

const rows = items.map(v => `<tr><td>${v.voucher_no || '—'}</td><td>${new Date(v.posting_date).toLocaleDateString('vi-VN')}</td><td>${v.partner_name}</td><td align="right">${vnd(v.total_amount)}</td><td>${STATUS_LABEL[v.invoice_status] || v.invoice_status}</td></tr>`).join('');

const html = `<h2>🧾 ${items.length} phiếu mua hàng chưa nhận hoá đơn đỏ</h2>`
  + `<p>Tổng giá trị: <b>${vnd(d.total_amount)}</b>. Gọi lại nhà cung cấp để đòi hoá đơn trước khi hết hạn khấu trừ thuế GTGT.</p>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><th>Số chứng từ</th><th>Ngày</th><th>Nhà cung cấp</th><th>Số tiền</th><th>Trạng thái</th></tr>${rows}</table>`
  + `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `🧾 ${items.length} phiếu chưa nhận hoá đơn — tổng ${vnd(d.total_amount)}`,
  email_html: html
} };
